/* Specificity comparison */
p { color: blue; }              /* (0,0,0,1) - element */
.text { color: green; }         /* (0,0,1,0) - class */
#main { color: red; }           /* (0,1,0,0) - id */
<p id="main" class="text" style="color: purple;">Hello</p>
/* Result: text is purple because inline style has highest specificity */

p { color: blue; }
p { color: green; }
/* Both have same specificity, so the later rule wins */
/* Result: text color will be green */

p {
  color: blue !important;
}
.text {
  color: green;
}
<p class="text">This will still be blue because of !important</p>

body {
  color: darkblue;
  font-family: Arial, sans-serif;
}
/* All text inside body, like in <p>, <h1>, <span>, will inherit color and font-family */

/* To force inheritance of a non-inherited property */
.child {
  border: inherit;
}
